import{_ as t,o as a,c as n,az as o,aQ as i,aR as r,aS as s,aT as l,aU as h}from"./chunks/framework.DXXa9EJF.js";const w=JSON.parse('{"title":"Organization","description":"","frontmatter":{},"headers":[],"relativePath":"guide/organization.md","filePath":"guide/organization.md"}'),d={name:"guide/organization.md"};function g(c,e,m,p,u,y){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="organization" tabindex="-1">Organization <a class="header-anchor" href="#organization" aria-label="Permalink to “Organization”">​</a></h1><p>Your Organization is the shared workspace that owns everything you create on ImagenHub — templates, generated media, credits, API keys, and provider keys — and lets you bring teammates in to work alongside you.</p><h2 id="what-an-organization-is" tabindex="-1">What an organization is <a class="header-anchor" href="#what-an-organization-is" aria-label="Permalink to “What an organization is”">​</a></h2><p>When you sign up, ImagenHub automatically creates an organization for you. There&#39;s no separate setup step — you&#39;re already the <strong>Owner</strong> of your own org from day one.</p><p>Think of it this way:</p><ul><li><strong>Your account</strong> is your login. On its own it doesn&#39;t own anything.</li><li><strong>Your organization</strong> owns the work: templates, media, credits, and keys all live here.</li><li><strong>Roles</strong> decide what each person can do inside the org.</li></ul><p>The important consequence: everything you create belongs to the organization, not to you personally. If you invite teammates, they share the same templates, media, and credits. And if someone leaves the org, they lose access to what&#39;s inside it — there&#39;s no personal storage that follows an account around.</p><p>You reach all of this from the <strong>Organization</strong> link in the left sidebar. It has four tabs: <strong>General</strong>, <strong>Members</strong>, <strong>Activity</strong>, and <strong>Roles</strong>.</p><h2 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to “General”">​</a></h2><p>The General tab is where you rename your organization.</p><p><img src="'+i+'" alt="Organization General tab showing the organization name field"></p><p>The name you set here is shown across the portal and on any invitations you send, so it&#39;s worth naming it something your team will recognize. Type a new name and click <strong>Save</strong>.</p><p>This tab also has a <strong>Leave organization</strong> option. Leaving means you lose access to that org&#39;s templates, tasks, and billing — so only use it if you truly want out. (If it&#39;s your only organization, you&#39;ll be asked to create a new one afterward.)</p><h2 id="members" tabindex="-1">Members <a class="header-anchor" href="#members" aria-label="Permalink to “Members”">​</a></h2><p>The Members tab is your team roster. It lists everyone in the organization along with their <strong>name, email, role, status, and when they were last active</strong>.</p><p><img src="'+r+'" alt="Organization Members tab showing the roster and Invite member button"></p><h3 id="inviting-a-teammate" tabindex="-1">Inviting a teammate <a class="header-anchor" href="#inviting-a-teammate" aria-label="Permalink to “Inviting a teammate”">​</a></h3><p>Click <strong>Invite member</strong> in the top-right corner to bring someone in.</p><p><img src="'+s+'" alt="Invite a teammate dialog with email and role fields"></p><ol><li>Enter their <strong>email address</strong>.</li><li>Pick the <strong>role</strong> they should have (Owner, Admin, Editor, or Viewer — see <a href="#roles">Roles</a> below).</li><li>Click <strong>Send invite</strong>.</li></ol><p>They appear in the roster right away as <strong>Invited</strong>, and an email goes out with a link that&#39;s valid for <strong>7 days</strong>. When they open it:</p><ul><li>If they&#39;ve never used ImagenHub, they set a name and password, then land in the dashboard.</li><li>If they already have a login, they go straight to the dashboard with their existing password.</li></ul><p>A few things worth knowing:</p><ul><li>Email is matched loosely — <code>A@Gmail.com</code> and <code>a@gmail.com</code> are treated as the same person.</li><li>You can&#39;t invite someone who&#39;s already in the org.</li><li>You can <strong>resend</strong> an invite while it&#39;s still pending, but not once it&#39;s been accepted.</li><li>The invite link is sensitive — anyone who has it can accept it, so don&#39;t forward it around.</li></ul><p>Click any row to open that member&#39;s details, where you can review or change their role, or remove them.</p><h2 id="activity" tabindex="-1">Activity <a class="header-anchor" href="#activity" aria-label="Permalink to “Activity”">​</a></h2><p>The Activity tab is a running log of what&#39;s happened in the organization, newest first.</p><p><img src="'+l+'" alt="Organization Activity tab showing recent activity entries"></p><p>It captures things like renaming the org, creating API keys, and other changes — a simple way to see recent actions at a glance without asking around.</p><h2 id="roles" tabindex="-1">Roles <a class="header-anchor" href="#roles" aria-label="Permalink to “Roles”">​</a></h2><p>The Roles tab explains what each of the four roles is allowed to do. <strong>Roles are fixed</strong> — you can&#39;t create custom ones or change what a role can do — but you assign one to every member from the Members tab.</p><p><img src="'+h+'" alt="Organization Roles tab showing the permissions matrix"></p><table tabindex="0"><thead><tr><th>Area</th><th>Owner</th><th>Admin</th><th>Editor</th><th>Viewer</th></tr></thead><tbody><tr><td><strong>Templates</strong> — create and edit templates</td><td>Manage</td><td>Manage</td><td>Manage</td><td>View</td></tr><tr><td><strong>Generations</strong> — run models and manage tasks</td><td>Manage</td><td>Manage</td><td>Manage</td><td>View</td></tr><tr><td><strong>API keys</strong> — issue and revoke keys</td><td>Manage</td><td>Manage</td><td>—</td><td>—</td></tr><tr><td><strong>Billing</strong> — plans, credits and payment</td><td>Manage</td><td>—</td><td>—</td><td>—</td></tr></tbody></table><p>In plain terms:</p><ul><li><strong>Owner</strong> — full control, including billing. Every org keeps at least one Owner.</li><li><strong>Admin</strong> — same as Owner, except they can&#39;t touch billing.</li><li><strong>Editor</strong> — can build and run templates and generations, but not keys or billing.</li><li><strong>Viewer</strong> — can look at templates and generated media, but can&#39;t create, run, or change anything.</li></ul><p>One thing that&#39;s true for <strong>everyone</strong>, regardless of role: the <strong>remaining credit balance is visible on the dashboard</strong>. Editors and Viewers can see how much is left, they just can&#39;t top up or change the plan.</p><h2 id="good-to-know" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know" aria-label="Permalink to “Good to know”">​</a></h2><p>A few common questions:</p><ul><li><strong>Deleting an organization</strong> isn&#39;t self-service — contact support if you need this.</li><li><strong>Custom roles</strong> aren&#39;t supported; the four roles above are fixed.</li><li><strong>Templates can&#39;t be recovered after leaving an org</strong> — they belong to the org, and access ends when your membership does.</li></ul><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to “Next steps”">​</a></h2><ul><li><a href="./authentication">Authentication</a> — how API keys and logins work.</li><li><a href="./templates">Templates</a> — the reusable presets your org shares.</li></ul>',41)])])}const f=t(d,[["render",g]]);export{w as __pageData,f as default};
